  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.AuditClaimRedated
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
# POST /api/sheets/{sheetId}/today — set the sheet's today (body: {today: yyyy-MM-dd, user}).
# A date that does not parse is refused (400) and nothing is stored. A new today records
# no line of its own, only the ROLLUP/TOTALS lines of the figures it moved. With grace days set, every
# open period whose to-date plus the grace days is before the new today is then closed (by to-date) as a
# close by hand would, each recorded as PERIOD_CLOSED ... auto=yes before the ROLLUP/TOTALS lines.
validate:
